        state: [E(.statement, 3, "Bookkeeper", "'I know that walk.'"), E(.digital, 2, "Phone Location", "{DL}'s phone off at 7 a.m."), E(.physical, 3, "Getaway Truck", "A truck from {D}'s cousin.", .search)],
        defense: [E(.statement, 1, "Fishing", "{DL} says {D.he} was fishing.")],
        role: "Mill bookkeeper",
        exam: [.direct("What is your job at the feed mill?", "\"I'm the bookkeeper. Every other Friday I pick up payroll cash from the bank and carry it into the mill office for the crew.\""), .direct("What happened at about 7 a.m. on {DATE}?", "\"Two people in masks stepped out of a truck as I was unlocking the office. One of them pointed a gun at me and took the bag with $19,000.\""), .direct("What could you see of the robbers?", "\"Not much. They wore masks and gloves, with hoods pulled up. One was taller, one stockier, and both moved quickly.\""), .direct("Why do you believe one of them was {D}?", "\"I recognized the walk. {D} was a driver here for years, and I watched that stride cross the yard every morning. A walk like that is hard to hide.\""), .direct("What happened to {D}'s employment?", "\"{D} was fired about thirty days before the robbery, after a dispute with the mill's owner. I wasn't part of the firing.\""), .direct("What happened after they left?", "\"They jumped back into a truck and drove off. About fifteen minutes later, at 7:15, a burning truck was reported on a back road.\""), .cross("Could you see {D}'s face?", "\"No. The mask covered the face, and I saw eyes only from a distance. My identification is from the walk and the build.\""), .cross("How far were you from the robbers?", "\"About fifteen feet at the closest. It was quick, and I was frightened. I'm not going to pretend I had a calm look.\""), .cross("Did the robbers say anything?", "\"One said hand it over. The voice was low and muffled behind the mask. I could not match it to anyone.\""), .cross("Was it light enough to see clearly?", "\"Sunrise was coming up, but the lot light was dim. The truck's headlights were in my eyes for a moment.\""), .cross("Has your identification of a person by a walk ever been wrong before?", "\"I have never had to do it before. I'm sure of what I saw, but I know it's not a face.\"")],
        defenseRole: "Fishing guide",
        defenseExam: [.direct("What do you do?", "\"I'm a fishing guide. I take people out on the lake at first light, and I know most of the regulars.\""), .direct("Did you see {D} on {DATE}?", "\"Yes. I saw {D}'s truck at the boat ramp before dawn. We said hello, and I watched {D} put a boat in the water.\""), .direct("What time was that?", "\"A little before 6:30, and I remember because I was setting up for a client at 6:45. {D} was heading out as I arrived.\""), .direct("How far is the lake from the mill?", "\"About forty minutes by road. It's a drive, but not a long one.\""), .direct("Did you see {D} again that morning?", "\"Not up close. I saw a boat out in the cove for part of the morning, and I assumed it was {D}'s.\""), .direct("How well do you know {D}?", "\"Well enough to know the truck and the boat. We have talked at the ramp for years.\""), .cross("Did you see {D} the entire morning?", "\"No. I saw {D} at the ramp and later thought I saw the boat. I can't account for every minute.\""), .cross("Could you tell it was {D} in the cove?", "\"Not for certain. It was a boat in the distance.\""), .cross("Could {D} have left the lake and come back?", "\"I suppose so. I wasn't watching.\""), .cross("Do you know about the robbery?", "\"Only what I heard after. I did not know anything that day.\""), .cross("Did you tell the deputies?", "\"Yes. I gave a statement as soon as I heard.\"")],
        theory: ("{D} robbed a mill.", "Fishing."),
        allocution: "\"I should have asked for help.\"",
        truths: ("{DL} had been fired.", "A fishing guide saw {DL}'s truck at the lake."),
        defendant: [.direct("Where were you at 7 a.m. on {DATE}?", "\"At a lake about forty minutes from the mill. I went fishing before dawn, as I often do on mornings off.\""), .direct("Why was your phone off?", "\"The reception is bad at the lake, and I turn it off to save battery. I did not turn it off for any reason connected to the mill.\""), .direct("Were you angry at the mill?", "\"I was fired about a month earlier, and yes, I was upset. I didn't rob anyone over it.\""), .direct("Do you know whose truck burned?", "\"I heard it belonged to a relative. I had no idea it was used for a robbery, and I did not lend it.\""), .direct("Did anyone see you at the lake?", "\"A fishing guide saw my truck at the lake that morning. We said hello at the boat ramp.\""), .direct("What did you do when the deputies came?", "\"I told them where I was and gave them the guide's name. I did not hide anything.\""), .cross("You worked at the mill for years, didn't you?", "\"Yes. I know the layout, the schedule, and who carries the cash. That's not a secret.\""), .cross("You were fired a month before, weren't you?", "\"Yes. It was a bitter ending.\""), .cross("The burning truck belonged to your relative, didn't it?", "\"So I'm told. I did not know it had been taken.\""), .cross("Your phone was off at 7 a.m., wasn't it?", "\"It was. I often turn it off while fishing.\""), .cross("You cannot prove you were at the lake, can you?", "\"I have the guide who saw my truck. That is what I have.\"")],
        openings: ("Two masked robbers took $19,000 in payroll cash at gunpoint from the feed mill bookkeeper. The bookkeeper recognized the walk of {D}, a driver fired a month earlier, and {D}'s phone was off at 7 a.m. The getaway truck belonged to a relative of {D}.", "{D} was fishing at a lake forty minutes away, and a fishing guide saw {D}'s truck at the boat ramp before dawn. A walk seen through a mask is not a face. The State must prove {D} was the robber."),
        closings: ("A fired driver, a walk the bookkeeper knew, a phone switched off, and a truck from {D}'s family that burned fifteen minutes later. The bookkeeper still shakes at the door. {D} had motive and knowledge of the schedule.", "A mask hides a face, and a walk is not proof. A fishing guide saw {D}'s truck at the lake at 6:30. The State must prove who was behind those masks."),
        timeline: [(-30, "{DL} is fired."), (0, "7 a.m.: the robbery."), (0, "7:15 a.m.: the truck burns."), (1, "{DL} is named.")],
