        defense: [E(.statement, 1, "Tips", "{DL} says the cash was tips.")],
        role: "Dollar store clerk",
        exam: [.direct("What is your job at the dollar store?", "\"I'm a clerk. I work the closing shift most nights, counting the drawer and locking up at ten.\""), .direct("What happened at about 9:50 p.m. on {DATE}?", "\"Someone in a gray hood walked up to the counter, held a pair of scissors toward me, and told me to open the register.\""), .direct("How would you describe the person?", "\"Tall, in a gray hooded sweatshirt, hood up, with a scarf over the lower face. I could see eyes but not much else.\""), .direct("What did you do?", "\"I opened the drawer and handed over the cash. The person took $380 and walked out quickly. I called 911 at 9:55.\""), .direct("What does the store camera show?", "\"A person in a hood holding scissors toward me at the register, then walking out with a handful of bills.\""), .direct("What happened afterward?", "\"Deputies stopped {D} about half an hour later, around 10:30, near the store, and searched {D}. They found $380 and scissors in {D}'s hoodie.\""), .cross("Could you see the person's face?", "\"No. The hood and scarf covered most of it. I told the deputies it was a tall person in a gray hood.\""), .cross("Did you recognize {D} at the show-up?", "\"I saw {D} in the patrol car lights. The build looked right, but I could not honestly say I recognized the face.\""), .cross("How long were the scissors pointed at you?", "\"Maybe ten seconds. I was focused on the blades and not on anything else.\""), .cross("Did you count the cash that was found on {D}?", "\"The deputies counted $380, which matched what I said was taken. I do not know whether it was the same bills.\""), .cross("Are there other gray hoodies in town?", "\"Of course. Gray hoodies are common. It is the whole outfit that made me think of {D}.\"")],
