        defenseRole: "Technician",
        defenseExam: [.direct("Was the counting machine off at times?", "\"Sometimes. It drifted, and we recalibrated it. I remember a ticket from before the failures.\""), .direct("Was it off on the nights the counts failed?", "\"Unknown. I do not have a record for those nights, so I cannot say if it drifted.\""), .direct("How does a miscalibrated counter cause trouble?", "\"It can count wrong, and a technician may fill a bottle with the wrong number. It does not change the tablet.\""), .direct("What is your role?", "\"I am a technician who works days and sometimes covers nights. I use the same counter.\""), .direct("What problems did you see with the counter?", "\"It sometimes jammed and miscounted tablets. We reported it to the supervisor.\""), .direct("What was done?", "\"A technician came and calibrated it. I do not know whether it was fixed.\""), .cross("Can a counter turn one tablet into a different tablet?", "\"No. It counts. It cannot create a look-alike. That would take a person.\""), .cross("Who can load tablets into the counter?", "\"Technicians and pharmacists. A person has to load the supply.\""), .cross("Did you see {D} load anything unusual?", "\"No. I did not see that. I only know about the counter.\""), .cross("You did not work the nights in question, did you?", "\"No. I worked other shifts.\""), .cross("You cannot say whether {D} swapped anything, can you?", "\"No. I only know the counter was unreliable.\"")],
        theory: ("{D} swapped pills.", "A bad counter."),
        allocution: "\"I needed help.\"",
        truths: ("{DL} had a prior injury.", "A calibration ticket predates the failures."),
        defendant: [.direct("Did you swap tablets in those bottles?", "\"No. I did not swap anything. I filled prescriptions as I always do, and the counter was off.\""), .direct("Why were counts failing on your shifts?", "\"The counter was miscalibrated. It was ticketed before the failures, and I think it caused the problem.\""), .direct("Do you have a prior injury?", "\"Yes. I had an injury before. It had nothing to do with this.\""), .direct("What is your role?", "\"I am a pharmacist on the night shift. I fill, count, and verify prescriptions.\""), .direct("Why were the counts off?", "\"The counter was miscalibrated and I had told the supervisor. It sometimes miscounts by a few tablets.\""), .direct("What do you say about the look-alike tablets?", "\"I did not put them in. I do not know how they got in the bottles.\""), .cross("Look-alike tablets were in six bottles from your shifts, weren't they?", "\"So the tests say. I do not know how they got there. I did not put them there.\""), .cross("You were alone at the counter, weren't you?", "\"Yes. That is how we work, one person at a time.\""), .cross("A counter counts. It does not make look-alikes, does it?", "\"No. I know that. I cannot explain the tablets.\""), .cross("You had a prior injury and took pills, didn't you?", "\"Yes, a back injury years ago. I was not taking pills from the pharmacy.\""), .cross("The failed counts were only on your shifts, weren't they?", "\"Yes. I cannot explain that.\"")],
