        exam: [.direct("What did the prescription database show about {D}'s practice?", "\"700 stimulant prescriptions written by {D}, a nurse practitioner, in six months. Visits were brief, and cash was collected at the door.\""), .direct("What did your undercover recording show during a visit?", "\"No exam at all. The script was handed over after a very short conversation, and the visit took only minutes.\""), .direct("What do the cash receipts and the charge sheet show?", "\"$80 per visit in cash. The charge sheet at the desk carried a price list that every patient could see.\""), .direct("What did you review?", "\"The state prescription database, which showed 700 stimulant prescriptions from {D} in six months. That is far above any peer.\""), .direct("What did patients pay?", "\"$80 in cash at the door, per visit. Receipts show the payments.\""), .direct("How did you choose the clinic as a target for the investigation?", "\"The prescription database flagged it as an outlier. Seven hundred scripts in six months was far above any peer, and we opened a review.\""), .cross("{D} says patients had real conditions, doesn't {D.he}?", "\"Several patients had prior diagnoses on record, and That is fair. Not every patient was faking.\""), .cross("Is it illegal for a clinic to collect cash from patients?", "\"No. It is not illegal in itself. But combined with the rest of what we found, it concerned us.\""), .cross("Did every patient who came to the clinic get a script?", "\"Most did. Not every single one, but the large majority left with a prescription in hand.\""), .cross("Charts list ADHD for patients, don't they?", "\"Yes. Several patients had prior diagnoses.\""), .cross("{D} was licensed to prescribe, wasn't {D.he}?", "\"Yes. The issue is whether the visits were real exams.\"")],
        defenseRole: "Receptionist",
        defenseExam: [.direct("Were patients examined at the clinic?", "\"Quick checks. {D} asked questions and took vital signs, and a short conversation followed.\""), .direct("Was every patient examined that way?", "\"No. Not every patient. Some returning patients just got a short chat.\""), .direct("How busy was the clinic?", "\"Very busy. The waiting room was always full, and {D} moved quickly from room to room.\""), .direct("What is your job at the clinic?", "\"I am the receptionist at {D}'s clinic. I greet patients, take payments at the door, and schedule the next visits for each of them.\""), .direct("How did visits usually go?", "\"Short, usually about fifteen minutes. {D} talked with each patient about their history and then wrote the script before they left the room.\""), .direct("What did patients tell you at the desk?", "\"Many said they had been diagnosed years earlier and just needed their medication. Some brought old records or pharmacy printouts to show me.\""), .cross("Did you see {D} hand over a script without any exam?", "\"I may have. I was at the front desk, and I did not see every visit.\""), .cross("Did you handle the cash?", "\"Yes. I collected $80 at the door for each visit.\""), .cross("Was there a price list?", "\"Yes. A charge sheet with prices was at the desk.\""), .cross("Patients paid before the visit, didn't they?", "\"Yes. They paid $80 at my desk first, and I gave them a receipt before they were called back.\""), .cross("You did not sit in on the exams, did you?", "\"No. I stayed at the front the whole time, so I cannot say what happened inside the exam room.\"")],
        theory: ("{D} sold prescriptions.", "Real patients."),
        allocution: "\"I lost my way.\"",
        truths: ("{DL} used a charge sheet with a price list.", "Several patients had prior diagnoses."),
        defendant: [.direct("Did you examine your patients before writing scripts?", "\"Briefly. I asked questions and checked what I could. I believed patients had real conditions.\""), .direct("Why did you collect cash at the door?", "\"Insurance was slow, and cash kept the clinic going. I charged $80 per visit.\""), .direct("Did patients really have conditions?", "\"Yes. Several had prior diagnoses, and I wrote scripts based on those.\""), .direct("How did you run your clinic?", "\"I saw many patients a day, mostly for attention problems. I tried to keep visits short and affordable.\""), .direct("What did you do in the visits?", "\"I reviewed history and prior diagnoses and wrote a script. I did not always do a full exam.\""), .direct("Why cash at the door?", "\"Many patients had no insurance. I charged $80 and gave receipts.\""), .cross("700 scripts in six months after brief visits. Isn't that too fast?", "\"It was busy. I did not take enough time. I see that now.\""), .cross("The undercover patient got a script without an exam, didn't they?", "\"I was rushed. I should have examined that person.\""), .cross("You used a charge sheet with a price list, didn't you?", "\"Yes. It was how we billed. I did not think it was wrong.\""), .cross("700 prescriptions in six months is a lot, isn't it?", "\"It is, and the clinic grew quickly.\""), .cross("You collected $80 in cash at the door before every visit, didn't you?", "\"Yes. It was how the clinic ran. I did not think about how that looked, and I should have used a billing system.\"")],
        openings: ("A nurse practitioner, {D}, wrote 700 stimulant prescriptions in six months after brief visits, collecting $80 in cash at the door. An undercover recording shows a script handed over without an exam.", "Jurors will hear that patients had real conditions, that several had prior diagnoses, and that {D} was busy and rushed, not running a mill."),
        closings: ("Seven hundred prescriptions in six months, $80 in cash at the door, and an undercover recording with no exam. This was a mill, not a practice.", "A busy practice with real patients and prior diagnoses on file. The State must prove {D} prescribed outside the course of professional practice."),
        timeline: [(-180, "The clinic opens."), (0, "Month 4: the audit."), (0, "Month 6: the sting."), (0, "Month 7: charges.")],
        identified: "A recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let cockfightBarnRaidV1 = SmallCases.make(
        key: "story.cockfightBarnRaid",
        category: .violent,
        headlines: ["Deputies Raid Dog Fighting Pit in Garage Behind Tire Shop", "Scarred Dogs Found Chained"],
        law: "animalCruelty",
        threshold: 7,
        spec: "Intentionally promoted and conducted animal fighting involving dogs, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies raided a garage behind a tire shop on {DATE} and found a pit and twelve scarred dogs. {D} owns the shop. {DL} says the garage was rented.",
        state: [E(.physical, 3, "Pit", "A blood-stained pit.", .search), E(.document, 3, "Deed", "{D} owns the property."), E(.forensic, 2, "Vet Reports", "Fresh bite wounds.")],
        defense: [E(.document, 1, "Rental Note", "A rental note.")],
        role: "Deputy",
        exam: [.direct("What led deputies to the garage behind the tire shop on {DATE}?", "\"We had a tip about a dog fight and had watched the property for a week. At about 9:30 p.m. we saw cars arriving and heard crowd noise from inside.\""), .direct("What did you find when you entered?", "\"A pit built in the center of the garage, with plywood walls stained dark. About twenty people stood around it, and twelve dogs were in crates and on chains.\""), .direct("What was the condition of the dogs?", "\"They were scarred, with old and fresh wounds on faces, legs and necks. Some had open bite marks that were still bleeding.\""), .direct("What did the veterinarian report?", "\"Fresh bite wounds on several dogs, consistent with fighting that night. The vet reports are in evidence.\""), .direct("Who owns the property?", "\"The deed shows {D} owns the shop and the garage behind it. We confirmed that with county records.\""), .direct("What happened at the gate?", "\"A person at the gate was collecting cash from arrivals. I saw bills changing hands when I watched from across the street.\""), .cross("Was {D} in the garage when you raided it?", "\"I did not see {D} in the garage. I'm not sure where {D} was at that moment.\""), .cross("Did you find a rental agreement?", "\"There was a handwritten rental note signed with a first name only. I didn't verify who that person was.\""), .cross("Did you identify the person at the gate?", "\"We detained several people at the gate and in the garage, and I did not personally see {D} take any cash from anyone arriving that night.\""), .cross("Did {D} say the garage was rented?", "\"Yes. {D} said it had been rented out a week earlier for a private event and that {D} did not ask what the event was.\""), .cross("Were the dogs owned by {D}?", "\"None of the twelve were registered to {D}. We have not yet determined who owned them, so nobody has been tied to the animals by paperwork.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("How do you know {D}?", "\"I live next to the shop and have for fifteen years. I see {D} most days, and we trade hellos over the fence.\""), .direct("Did you see activity at the garage that week?", "\"Yes. A few cars came and went, mostly at night, and someone had put a sign on the side door.\""), .direct("Did you see {D} there?", "\"I saw {D} in the front of the shop during the day. I did not see {D} around the garage at night.\""), .direct("Did you hear anything the night of the raid?", "\"A lot of cars and a crowd. I figured it was a party, but I noticed the dogs barking too.\""), .direct("Did you know what was happening?", "\"Not until deputies came that night. I assumed it was a car club or a party, because the cars were nice and nobody looked rowdy from my fence.\""), .direct("Have you ever known {D} to do anything like this?", "\"No, never. {D} runs the tire shop honestly, fixed a flat for me once without charging, and has always been decent and quiet with the neighbors.\""), .cross("Did you see who rented the garage?", "\"No. I saw someone with a truck come and go, but I could not describe that person.\""), .cross("Did you see {D} talk to that person?", "\"Once, I believe, a couple of days before the raid. They stood by the garage door for about a minute, and then the other person drove off.\""), .cross("Did you see the dogs?", "\"I heard them barking and yelping, but I never saw the dogs. The garage door stayed closed, and I could only hear it from my own yard.\""), .cross("Do you know whether {D} was at the garage that night?", "\"I do not. I was inside my house that night with the television on, and I did not see who was at the shop or who was not.\""), .cross("Did you call anyone?", "\"No. I thought it was a party, since there was music and a lot of cars, and it never occurred to me to call anyone.\"")],
        theory: ("{D} ran a dog fight.", "A landlord."),
        allocution: "\"I'm ashamed.\"",
        truths: ("{DL} had cash at the gate.", "The note is signed with a first name."),
        defendant: [.direct("What is your relationship to the property?", "\"I own the tire shop and the garage behind it. I run the front, and the garage was rented out a week before the raid.\""), .direct("Who rented it?", "\"A person who gave a first name only. I signed a note, took cash up front, and handed over a key.\""), .direct("What did the renter say it was for?", "\"Storage and a private party. I did not ask for details. I assumed it was a car club.\""), .direct("Were you at the garage that night?", "\"I was at home. I did not go near the garage, and I did not know what was going on in it.\""), .direct("How did you learn about the raid?", "\"A deputy called me at about 9:45 and told me what they found. I drove over right away.\""), .direct("What would you do differently?", "\"Check who I rent to and go look at what's happening on my own property.\""), .cross("You own the building where the dog fight took place, don't you?", "\"Yes. I own the garage and the shop in front of it, and I take responsibility for who was inside it, even though I never went in that week.\""), .cross("The rental note is signed with a first name only, isn't it?", "\"Yes. The note has a first name and nothing else. I took the note and the cash, handed over a key, and I did not ask for any identification.\""), .cross("You had cash from that renter, didn't you?", "\"Yes, one week's rent in cash, paid up front. It did not seem strange to me at the time, because plenty of people pay cash at the shop.\""), .cross("You never visited the garage that week, did you?", "\"No. I never looked inside that garage the whole week it was rented. I figured it was private, and I should have gone and seen for myself.\""), .cross("A blood-stained pit does not appear in a day, does it?", "\"I have no idea how long a pit like that takes to build, and I never saw it. If it was built in that week, I was not there when it happened.\"")],
        openings: ("Deputies raided a garage behind {D}'s tire shop on a Friday night and found a blood-stained pit, twenty spectators, and twelve scarred dogs with fresh bite wounds. The deed shows {D} owns the building, and cash was changing hands at the gate. You will hear from the deputy who led the raid.", "{D} rented the garage a week earlier to someone who gave only a first name and said it was storage. {D} was not there that night, and a neighbor will tell you how the property looked from outside. The State must prove {D} knew and took part."),
        closings: ("A pit, a crowd, a gate taking cash, and twelve dogs cut up in a garage that {D} owns. The rental note is a first name on a scrap of paper. Property owners answer for what happens on their property.", "A rental to someone who gave a first name, a night when {D} was at home, and a neighbor who thought it was a car club. No one saw {D} at the gate. The State must prove {D} ran this event."),
        timeline: [(-7, "The rental."), (0, "9 p.m.: the fight."), (0, "9:30 p.m.: deputies."), (0, "10 p.m.: dogs seized.")],
        identified: "A deed.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let carChokeBarV1 = SmallCases.make(
        key: "story.carChokeBar",
        category: .violent,
        headlines: ["Man Chokes Partner in Hotel Stairwell After Wedding", "Housekeeper Hears a Thud"],
        law: "strangulation",
        threshold: 7,
        spec: "Assaulted {V} by strangling, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was found with neck marks in a hotel stairwell after a wedding on {DATE}. A housekeeper heard a thud and saw {D} leaving. {DL} says {V} fell on the stairs.",
        state: [E(.forensic, 3, "Medical Report", "Neck marks and petechiae."), E(.statement, 3, "Housekeeper", "'I heard a thud and saw {D}.'"), E(.video, 2, "Stairwell Camera", "{D} leaves quickly.")],
        defense: [E(.statement, 1, "Fall", "{DL} says {V} fell on the stairs.")],
        role: "Housekeeper",
        exam: [.direct("What is your job at the hotel?", "\"I'm a housekeeper on the evening shift. On {DATE} a wedding was being held in the ballroom, and I was cleaning the third floor and stairwells.\""), .direct("What did you hear at about 11:05 p.m.?", "\"A loud thud in the stairwell, like something heavy hitting the landing. It made me stop, and I went toward the sound.\""), .direct("What did you see?", "\"I saw {D} leaving the stairwell quickly, walking fast and not looking at me. When I got inside, I found {V} on the landing.\""), .direct("What was {V}'s condition?", "\"{V} was on the floor, awake but gasping, with red marks on the neck and a hoarse voice. {V} could not speak for several minutes.\""), .direct("What did you do?", "\"I used my radio to call security and the front desk, and I stayed with {V}. At about 11:10 I was joined by other staff.\""), .direct("What does the stairwell camera show?", "\"{D} leaving quickly at about 11:05, matching what I saw. The camera is at the landing above, facing the door.\""), .cross("Did you see {D} touch {V}?", "\"No. I only heard the thud and saw {D} leave. I did not see what happened on the landing.\""), .cross("Were the stairs wet that night?", "\"There had been a spill from the reception earlier. I do not know if the landing was wet at the time of the thud.\""), .cross("Could {V} have fallen?", "\"It's possible, I suppose. But the neck marks do not look like a fall to me, and I'm not a doctor.\""), .cross("How far were you from the stairwell door when you heard it?", "\"About twenty feet down the hall. I walked there in a few seconds and saw {D} leave.\""), .cross("Did {D} say anything to you?", "\"No. {D} passed me in the hallway without a word and went off toward the ballroom, walking fast with eyes straight ahead.\"")],
        defenseRole: "Banquet server",
        defenseExam: [.direct("What is your job at the hotel?", "\"I'm a banquet server. I worked the wedding that evening, carrying trays between the kitchen and the ballroom.\""), .direct("Did you see the spill?", "\"Yes. A tray of drinks went down near the stairwell door around ten thirty. I helped wipe it but it was not completely dry.\""), .direct("Did you see {D} and {V} at the reception?", "\"I saw them talking at a table, and it looked tense. At one point {D} took hold of {V}'s arm.\""), .direct("What did you do?", "\"I stepped over and asked if everything was all right. {D} let go and said it was fine.\""), .direct("Did you see them leave?", "\"I saw {V} head toward the stairwell, and a minute or two later {D} followed.\""), .direct("What did you hear afterward?", "\"About a thud, and the staff running to the stairwell. I stayed in the ballroom to calm the guests.\""), .cross("Did you see what happened in the stairwell?", "\"No. I was in the ballroom. I only saw them go toward the door.\""), .cross("Did you hear them argue?", "\"I heard some raised voices at the table. I couldn't tell what was said.\""), .cross("Was the spill still wet at 11?", "\"I am not sure. The spill happened around ten thirty and the fall was around eleven, so it had been about half an hour, and I never went back to check it.\""), .cross("Did you see marks on {V}'s neck?", "\"No. I only saw {V} after the ambulance came, and the lights were low.\""), .cross("Do you know {D}?", "\"Only as another guest at the wedding. I had never spoken to {D} before that night, so I cannot say much about {D.him} beyond what I saw at the tables.\"")],
        theory: ("{D} choked {V}.", "A fall."),
        allocution: "\"I never meant to.\"",
        truths: ("{DL} had grabbed {V} earlier at the reception.", "The stairs were wet from a spill."),
        defendant: [.direct("Why were you in the stairwell at about 11 p.m.?", "\"I was heading to the parking garage to leave the reception. The stairwell was the quickest way down from the ballroom.\""), .direct("What did you see on the stairs?", "\"{V} was coming down ahead of me and slipped on a wet step from a spill. {V} fell hard on the landing.\""), .direct("Did you touch {V}?", "\"I reached out to catch {V}, and I may have grabbed {V}'s collar or neck. I was trying to stop the fall.\""), .direct("Why did you leave?", "\"I panicked and thought someone else would help. I should have stayed, and I regret leaving {V} there.\""), .direct("Had you argued with {V} earlier?", "\"We had words at the reception, and I grabbed {V} by the arm at one point. I'm not proud of it.\""), .direct("What did you tell the deputy?", "\"That {V} fell, and that I was trying to catch {V}. I told them about the spill.\""), .cross("You grabbed {V} earlier at the reception, didn't you?", "\"Yes. It was a heated moment, and I apologized. It was not a choke.\""), .cross("You left the stairwell right after the fall, didn't you?", "\"Within a few seconds. I went back up toward the ballroom because I did not know what else to do, and I told myself someone would come.\""), .cross("{V} has marks on the neck, doesn't {V.he}?", "\"I have heard that. I don't know how they happened, other than my trying to catch {V}.\""), .cross("You never called for help, did you?", "\"No. I assumed the housekeeper would call for help, since the housekeeper was right there. Looking back, that was a wrong assumption and I should have stayed.\""), .cross("You and {V} were alone on that landing, weren't you?", "\"For a few seconds, yes. It was only the two of us on that landing before I turned and went back up the stairs.\"")],
        openings: ("{V} was found on a hotel stairwell landing after a wedding, with marks on the neck and unable to speak. A housekeeper heard a thud and saw {D} leave quickly, and the stairwell camera confirms it. You will hear from the housekeeper and see the medical report.", "{D} says {V} slipped on a wet step and fell, and {D} reached to catch {V}. A banquet server will tell you about the spill near the stairwell door. {D} panicked and left, which is not the same as choking {V}."),
        closings: ("A thud at 11:05, {D} leaving quickly, and {V} on the landing with neck marks and petechiae. {D} had grabbed {V} earlier that night. The housekeeper heard and saw it.", "A spill, a wet step, a fall, and a person who tried to catch {V} and then panicked. No one saw a choke. The State must prove the neck marks came from {D}'s hands and not from a fall."),
        timeline: [(0, "11 p.m.: the stairwell."), (0, "11:05 p.m.: the thud."), (0, "11:10 p.m.: the housekeeper."), (0, "Midnight: {DL} is arrested.")],
        identified: "A housekeeper.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I couldn't speak for days.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let gpsTrackerExV1 = SmallCases.make(
        key: "story.gpsTrackerEx",
        category: .violent,
        headlines: ["Ex-Partner Planted AirTag in Purse and Waited at Appointments", "Notification Warned Her"],
        law: "stalking",
        threshold: 7,
        spec: "Willfully harassed {V} on more than one occasion without legitimate purpose, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} got a tracker alert on {DATE} and found an AirTag in {V.his} purse. {D}, an ex-partner, had appeared at {V.his} appointments. {DL} says {D.he} found the tag.",
        state: [E(.physical, 3, "AirTag", "In the purse; registered to {D}."), E(.statement, 3, "Receptionist", "{D} waited in the lot."), E(.digital, 2, "Tag Records", "Locations match {D}'s visits.")],
        defense: [E(.statement, 1, "Found", "{DL} says {D.he} found the tag.")],
        role: "Clinic receptionist",
        exam: [.direct("What is your job at the clinic?", "\"I'm a receptionist at a medical clinic. I check in patients, schedule appointments, and keep an eye on the waiting room and parking lot.\""), .direct("How do you know {V}?", "\"{V} is a regular patient. Over several weeks {V} had a series of appointments, and I saw {V} at the desk each time.\""), .direct("What did you notice about {D}?", "\"{D} showed up in the clinic lot at several of {V}'s appointments. {D} would wait in a car and watch the entrance. {V} was visibly uneasy.\""), .direct("Did {D} come inside?", "\"No. {D} stayed in the lot each time. {D} did not check in, and when I walked out to ask, {D} drove off.\""), .direct("What did {V} tell you?", "\"{V} said {D} was an ex-partner who had not accepted the breakup, and that {V} had asked {D} to stay away.\""), .direct("What happened afterward?", "\"About three weeks into the pattern, {V} got a tracker alert and found an AirTag in {V}'s purse. {V} called the Sheriff's Office from our waiting room.\""), .cross("Did you see {D} place anything in {V}'s purse?", "\"No. I never saw {D} near {V}'s belongings. I only saw {D} in the parking lot.\""), .cross("Did you speak with {D} directly?", "\"Once, through the car window. {D} said {D.he} was waiting for a friend. I asked {D.him} to move and {D} left.\""), .cross("How many appointments did {D} show up at?", "\"Three or four that I recall. I could not count exactly, but there was a pattern.\""), .cross("Did {V} ever say {V.he} gave {D} the schedule?", "\"Not that I know of. I do not know how {D} learned the times.\""), .cross("Is it possible {D} was just parking near the clinic?", "\"The clinic has a shared lot. Other people park there. But {D} was watching the door, and {V} noticed that too.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("How do you know {D}?", "\"I have known {D} for years from our neighborhood, and I watched {D} go through the breakup. I was around a lot afterward, and I heard plenty about {V}.\""), .direct("Did {D} mention an AirTag?", "\"Yes. {D} said {D.he} had found one in a box of {V}'s old things and was surprised.\""), .direct("What did {D} do with it?", "\"{D} said {D.he} brought it to {V}'s attention, and {V} was angry. {D} told me {D.he} did not put it there.\""), .direct("How was {D} after the breakup?", "\"Sad and obsessed. {D} wanted to know that {V} was okay. I told {D} to leave {V} alone.\""), .direct("Did {D} drive to the clinic?", "\"{D} told me {D.he} did, because {D.he} was worried. I told {D.him} that was not okay.\""), .direct("What did you tell {D}?", "\"I told {D} to give {V} some space and stop showing up at {V}'s appointments. {D} nodded and said {D.he} understood, but I am not sure it sank in.\""), .cross("Did you see {D} put the AirTag anywhere?", "\"No. I never saw {D} put the tag anywhere, and I was never present when {D} handled {V}'s belongings.\""), .cross("Did you know the AirTag was registered to {D}?", "\"I did not know that at the time. I only learned the tag was registered to {D} later, when the Sheriff's Office called me.\""), .cross("Did {D} tell you about the written request to stop?", "\"Yes, {D} showed me the message on {D.his} phone. It was clear and polite, and {D} admitted that {D.he} had not followed it.\""), .cross("Did you tell {D} to delete the tracker?", "\"I told {D} to stay away from {V} entirely. I do not remember saying anything specific about the tracker itself, only that {D} should stop.\""), .cross("Do you believe {D}?", "\"I believe {D} was lonely and not thinking. I truthfully cannot say what happened with that tag, because I was not there when it was placed.\"")],
        theory: ("{D} tracked an ex.", "A found tag."),
        allocution: "\"I crossed a line.\"",
        truths: ("{DL} had been told in writing to stop.", "The tag was registered months earlier."),
        defendant: [.direct("What was your relationship with {V}?", "\"We were partners for a couple of years. We broke up about a month before the clinic visits, and I was not ready to let go.\""), .direct("Why were you in the clinic parking lot?", "\"I wanted to see {V} and make sure {V} was okay. I know that sounds wrong, but I was worried.\""), .direct("Did you put an AirTag in {V}'s purse?", "\"No. I found an AirTag in a place I'd left some items for {V}, and I picked it up. I did not put it in the purse.\""), .direct("Whose AirTag was it?", "\"It was registered to me, months earlier. I used it for my keys and a bag, and I left it in a box of items I returned to {V}.\""), .direct("Why did you not tell {V}?", "\"I did not realize it was in the box. When I found out, I felt sick.\""), .direct("Were you told to stay away?", "\"Yes. {V} asked me in writing to stop contacting {V}. I did not follow it.\""), .cross("You were in the lot at three or four appointments, weren't you?", "\"Yes, three or four of them. I should not have been there at all. I told myself I was only checking on {V}, but I was not thinking clearly.\""), .cross("The AirTag locations match your visits, don't they?", "\"That is what the records say, and it makes sense, because the tag traveled with {V}'s purse. I am not saying the records are wrong, only that I did not put it there.\""), .cross("You received a written request to stop contact, didn't you?", "\"Yes, I received it and read it. It was clear and polite. I did not obey it, and I have no good reason for that.\""), .cross("You never told {V} about the AirTag, did you?", "\"No. I did not know the tag was in the box of returned items until {V} got the alert. I never told {V} because I did not know.\""), .cross("You registered that AirTag months before, didn't you?", "\"Yes. I bought it months earlier for my own keys and registered it then, which is why the records show my name on it.\"")],
        openings: ("{V} found an AirTag in {V}'s purse after an alert on a phone. The tag was registered to {D}, an ex-partner who had appeared in the clinic lot at several of {V}'s appointments, and the tag's locations match those visits. You will hear from the receptionist who saw {D} in the lot.", "{D} found an AirTag in a box of old items and returned it, and the tag was a leftover from {D}'s own keys. A friend will tell you {D} was grieving, not stalking. The State must prove {D} placed the tag."),
        closings: ("A tag registered to {D}, found in {V}'s purse, with locations that match {D}'s visits to the clinic lot. {V} had told {D} in writing to stop. {V} looked over {V.his} shoulder everywhere.", "A tag registered months earlier and a box of belongings {D} returned. {D} did not hide the visits and did not put anything in the purse that anyone saw. The State must prove {D} placed the tag."),
        timeline: [(-30, "The breakup."), (0, "Week 1: the clinic."), (0, "Week 3: the alert."), (1, "{DL} is arrested.")],
        identified: "An AirTag.",
        mood: .wantsConviction,
        impact: "I looked over my shoulder everywhere.",
