        impact: "I stopped going online.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let doorbellHackFamiliesV1 = SmallCases.make(
        key: "story.doorbellHackFamilies",
        category: .cyber,
        headlines: ["Man Hacked Baby Monitors and Narrated to Parents", "Voices Through a Nursery Speaker"],
        law: "accessingComputers",
        threshold: 7,
        spec: "Accessed computers of {V} without authority, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A voice spoke through a baby monitor speaker on {DATE}. Logins traced to {D}. {DL} says {D.he} was testing passwords.",
        state: [E(.digital, 3, "Login Log", "Logins from {D}'s address."), E(.digital, 3, "Monitor Records", "A remote voice session."), E(.document, 2, "Warrant Return", "A list of monitor accounts.")],
        defense: [E(.statement, 1, "Testing", "{DL} says {D.he} was testing passwords.")],
        role: "Cyber investigator",
        exam: [.direct("What is your role in this case?", "\"I'm a cyber investigator. I was assigned after several families reported a stranger's voice coming from their baby monitors at night.\""), .direct("What happened on {DATE}?", "\"A voice spoke through a baby monitor speaker in a family's home, in the middle of the night. The parents heard it and immediately unplugged the device.\""), .direct("How did you trace it?", "\"The monitor maker's records show a remote voice session at that time, logged in from an address that belongs to {D}.\""), .direct("What do the login records show?", "\"Logins from {D}'s address going back about two weeks, testing multiple monitor accounts. The first login was fourteen days before the voice.\""), .direct("What did the warrant return show?", "\"A list of monitor accounts that had been accessed from {D}'s network. It was a long list, dozens of families.\""), .direct("What happened after the voice session?", "\"The family called the Sheriff's Office. Within a day I had the login records, and a few days later {D} was arrested.\""), .cross("Did the logins prove a person was speaking?", "\"They show a remote voice session on the account. They do not name the speaker.\""), .cross("Could someone else have used {D}'s network?", "\"A roommate and other people lived at that address. The records do not separate them.\""), .cross("Did {D} say anything about security testing?", "\"{D} said {D.he} was testing passwords on accounts, as a hobby. I did not verify that story.\""), .cross("Did the families suffer physical harm?", "\"No. But they were terrified. Parents threw out the monitor and some moved the nursery.\""), .cross("Were any passwords weak or reused?", "\"Many were. That is how the accounts were accessed. The manufacturer has changed its policy.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("How do you know {D}?", "\"We share an apartment and have lived together for about two years. I see {D} most evenings, and our rooms are on opposite sides of the hall.\""), .direct("What does {D} do?", "\"{D} works in IT support and runs a small blog about security. {D} tests things on a spare computer.\""), .direct("Did you see {D} testing passwords?", "\"Yes. {D} would run lists and read logs at night. It was a hobby.\""), .direct("Did you ever use {D}'s network for anything like that?", "\"No. My own use of the network is streaming and email, and I am rarely on it for more than an hour at a time.\""), .direct("How did {D} react to the investigation?", "\"{D} was shaken. {D} said it was a stupid test that went too far.\""), .direct("Did {D} talk about baby monitors?", "\"{D} mentioned that default passwords were terrible. I did not know {D} had tried them.\""), .cross("Did you see {D} speak into a monitor?", "\"No. I never saw {D} speak into a monitor or anything like it, and I never heard {D}'s voice coming from a speaker either.\""), .cross("Were you home during the sessions?", "\"For some of them, yes. I was home on several of those nights, but I did not watch what {D} was doing at the computer.\""), .cross("Did you hear a voice from {D}'s room?", "\"No. I would remember hearing a voice like that from {D}'s room, and nothing like it ever came through the wall.\""), .cross("Did you know about the list of accounts?", "\"No. I learned about the list from the deputies, and I had never seen it or heard {D} mention keeping one.\""), .cross("Do you know who else used {D}'s network?", "\"Only guests, mostly. Friends would drop in for an evening, but nobody stayed long enough to be a regular user of the network.\"")],
        theory: ("{D} hacked a baby monitor.", "Testing."),
        allocution: "\"I'm sorry for the family.\"",
        truths: ("{DL} spoke on the session.", "{DL} runs a security blog."),
        defendant: [.direct("Why were you logging into those monitor accounts?", "\"I was testing passwords. I run a small security blog and wanted to see how bad the default passwords were.\""), .direct("Did you speak to a family?", "\"I'd rather not go into every detail. It was a careless test, and I did something I should not have done.\""), .direct("Why did you test other people's accounts?", "\"It was a bad idea. I told myself I was proving a point about weak security. I did not think about the families.\""), .direct("How many accounts did you try?", "\"Dozens. I kept a list for my own notes. I did not use the list for anything else.\""), .direct("Do you understand how it felt to a parent?", "\"Yes, and I am horrified. If a stranger's voice came out of my own child's monitor at night, I would feel exactly the same terror.\""), .direct("What would you do differently?", "\"Never touch accounts that are not mine. I should have reported the weakness instead.\""), .cross("You logged into accounts that belonged to other people, didn't you?", "\"Yes, I did. I logged into accounts that belonged to other people without their permission, and I knew they were not mine when I did it.\""), .cross("One of those sessions included a voice, didn't it?", "\"That is what the records say, and I am not going to argue with them. It was a reckless thing to do, and I regret it deeply.\""), .cross("You did that for two weeks, didn't you?", "\"Over about that long, yes. It started as testing and kept going further than it should have before I stopped.\""), .cross("You kept a list of accounts, didn't you?", "\"I did keep a list for my own notes. It is the same list that showed up in the warrant return, and I did not use it for anything else.\""), .cross("You never contacted the manufacturer, did you?", "\"No, I never contacted the manufacturer. I should have reported the weak passwords instead of trying them on real families.\"")],
        openings: ("A stranger's voice came through a baby monitor speaker in a family's home in the middle of the night. The manufacturer's logs show a remote voice session and weeks of logins from {D}'s address, and the warrant return lists dozens of monitor accounts. You will hear from the cyber investigator.", "{D} says {D.he} was testing password strength for a hobby blog, and a roommate will confirm {D} runs a blog and tests on a spare computer. {D} never meant to frighten anyone. The State must prove {D} was the voice."),
        closings: ("Two weeks of logins from {D}'s address, dozens of monitor accounts, and a voice in a nursery in the middle of the night. A family threw out the monitor. The records point to one address.", "A roommate describes a security hobby and a blog, and the records show logins but not a speaker. The State must prove who spoke through that monitor."),
        timeline: [(-14, "The first login."), (0, "The voice."), (0, "The call."), (1, "{DL} is arrested.")],
        identified: "Login logs.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "We threw out the monitor.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let schoolRansomLockV1 = SmallCases.make(
        key: "story.schoolRansomLock",
        category: .cyber,
        headlines: ["County Library Catalog and Records Locked by Ransom Note", "Contractor Account Used at Night"],
        law: "damagingComputers",
        threshold: 8,
        spec: "Willfully caused damage to computers of {V}, a library system, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A library system's records were locked on {DATE} with a $25,000 note. A contractor login tied to {D} was used. {DL} says the login was shared.",
        state: [E(.digital, 3, "Access Log", "The contractor login at 2 a.m."), E(.digital, 3, "Wallet Trace", "Funds tied to {D}."), E(.document, 2, "Ransom Note", "A $25,000 demand.")],
        defense: [E(.statement, 1, "Shared", "{DL} says the login was shared.")],
        role: "Library IT director",
        exam: [.direct("What happened to the library system's records?", "\"They were locked with a $25,000 ransom note. The note arrived the same night as the lockout of the whole system.\""), .direct("What does the access log show about the attack?", "\"A contractor login tied to {D} used at 2 a.m. to get into the system. That is the login that opened the door.\""), .direct("What did the wallet trace show about the ransom?", "\"Funds tied to {D}. The wallet had received a payment from a forum, and that payment was linked back to {D}.\""), .direct("What happened to the library systems?", "\"At 2 a.m. the records were locked and a note demanded $25,000. By 8 a.m. staff were locked out of the catalog and patron accounts.\""), .direct("What did the access log show?", "\"A contractor login connected at 2 a.m. That login had been reset a month earlier and was used from an unfamiliar address.\""), .direct("What did you do after the library records locked?", "\"We pulled the network offline, preserved the logs and called the sheriff's office. We then restored what we could from backups that were a few days old.\""), .cross("{D} says the login was shared, doesn't {D.he}?", "\"Yes. The login had also been reset a month earlier, and I will say that is part of the picture.\""), .cross("Was a new login issued to {D} after the reset?", "\"Yes. {D} received a new login after the reset. The older login should not have worked at all.\""), .cross("Could someone else have used {D}'s old login at 2 a.m.?", "\"It is possible. I cannot rule it out. Several people had access to that old login over time.\""), .cross("The login was shared, wasn't it?", "\"It was assigned to a contractor team, so more than one person knew it.\""), .cross("Many people knew the login, didn't they?", "\"Several contractors and staff did. That makes attribution harder.\"")],
        defenseRole: "Library clerk",
        defenseExam: [.direct("Was the contractor login reset before the attack?", "\"Yes. We reset it about a month before the attack, as part of normal rotation, and I handled the ticket.\""), .direct("Was the new login given to {D} after the reset?", "\"Yes. {D} received the new login from me, and I handed it over myself at the front desk.\""), .direct("Were the old logins still working after the reset?", "\"They should not have been. I do not know why one of them still worked on the night of the attack.\""), .direct("What is your job?", "\"I am a library clerk. I use the catalog and patron accounts every day.\""), .direct("What happened on the day?", "\"Staff computers froze and a note appeared on screen. We lost access for several days.\""), .direct("What do you know about the login?", "\"I heard that contractors shared logins. That was common.\""), .cross("Who had access to the old login before it was reset?", "\"Several contractors and staff members. It was passed around for years, and nobody tracked who held it.\""), .cross("Did you see {D} use the login at 2 a.m. that night?", "\"No. I was not there at that hour. I only know about what the access log shows, nothing more.\""), .cross("Did {D} ever talk about selling logins to anyone?", "\"No. I never heard {D} say anything like that, and I would remember if I had.\""), .cross("You do not know who used the login at 2 a.m., do you?", "\"No. I was at home that night asleep, so I can only repeat what the staff meeting told us afterward.\""), .cross("You do not know who owns the wallet, do you?", "\"No. I only know what the IT director announced to the whole library the next day.\"")],
        theory: ("{D} locked records.", "A shared login."),
        allocution: "\"I regret it.\"",
        truths: ("The wallet received a payment from a forum.", "The login was reset a month earlier."),
        defendant: [.direct("Did you lock the library's records?", "\"No. I did not lock anything or send any note.\""), .direct("Whose login was used at 2 a.m.?", "\"It was a login like mine. I got a new one after the reset. The old one was shared.\""), .direct("What was your work for the library?", "\"I was a contractor who maintained the systems and handled updates. I had a login for that.\""), .direct("Who else used your login?", "\"A coworker used it at times for tasks. We shared it because the system was slow to issue accounts.\""), .direct("What about the wallet?", "\"I have a wallet for other work, but the payment from a forum was for a freelance job.\""), .direct("What did you do when you heard the library's records had been locked?", "\"I checked my own devices and the contract paperwork. I told the library that my login might have been used by someone else.\""), .cross("The wallet received a payment from a forum, didn't it?", "\"I do not know. I did not use a forum for that.\""), .cross("The login used belongs to you, doesn't it?", "\"It was reset a month before. I do not know why it worked.\""), .cross("You are a contractor with access to the system, aren't you?", "\"Yes. That does not mean I used it to attack it.\""), .cross("The ransom note referred to your wallet, didn't it?", "\"The wallet matches mine. I did not send the note.\""), .cross("The login was reset a month earlier, wasn't it?", "\"Yes. I thought only I had the new one.\"")],
        openings: ("A library system's records were locked with a $25,000 ransom note. A contractor login tied to {D} was used at 2 a.m., and funds from the forum payment were tied to a wallet linked to {D}.", "The defense case is that the login was reset a month earlier and shared among others, and that the wallet link may not be {D}'s."),
        closings: ("A contractor login at 2 a.m., a ransom note, and a wallet tied to {D}. The attack came in through {D}'s own door, and the money trail leads back there.", "A shared login that was reset a month before, and a wallet that may not be {D}'s at all. The State must prove {D} launched the attack."),
        timeline: [(-30, "The login reset."), (0, "2 a.m.: the attack."), (0, "8 a.m.: staff locked out."), (1, "The trace.")],
        identified: "Logs and a wallet.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        impact: "Patrons lost access.",
        doctrines: ["burdenOfProof"])

    static let bankFileSaleV1 = SmallCases.make(
        key: "story.bankFileSale",
        category: .cyber,
        headlines: ["Insurance Agency Clerk Sold Policyholder Files to Scammers", "Claims Phished the Same Week"],
        law: "identityTheft",
        threshold: 8,
        spec: "Knowingly obtained and sold identifying information of {V}, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Scammers phished policyholders after an agency clerk, {D}, sold files on {DATE}. Chats showed {D} sending files for pay. {DL} says the exports were for a mailing.",
        state: [E(.digital, 3, "Chat Messages", "{D} sends files."), E(.digital, 3, "Access Log", "{D} exported 70 files."), E(.document, 2, "Payment Record", "Crypto payments to {D}.")],
        defense: [E(.statement, 1, "Mailing", "{DL} says the exports were for a mailing.")],
        role: "Agency security officer",
        exam: [.direct("What is your role at the agency?", "\"I'm the agency's security officer. I monitor access to policyholder files, investigate suspicious activity, and work with outside investigators.\""), .direct("What happened that led you to investigate?", "\"About four weeks after exports began, policyholders started reporting phishing calls and emails that used their policy details. That made us look at who had pulled the files.\""), .direct("What did the access log show?", "\"{D} exported seventy policyholder files over a month. The log has the times, the file names, and the terminal.\""), .direct("What did the chats show?", "\"Chat messages between {D} and an alias, with {D} sending files and the alias confirming receipt. The chats were recovered on a warrant.\""), .direct("What about payment?", "\"Records show cryptocurrency payments to {D} after the file transfers. The amounts match the number of files sent.\""), .direct("What was the effect on policyholders?", "\"Many were phished, some lost savings. One investor told me the scammers used details only the agency had.\""), .cross("Did {D} have a work reason to export files?", "\"Clerks occasionally export for mailings. But {D} had no assignment for a mailing that month.\""), .cross("Did the manager approve any mailing?", "\"The manager says a mailing was discussed in passing. I never saw a written assignment.\""), .cross("Is the alias in the chat identified?", "\"No. The alias in the chat has not been traced to a real person, so we do not know who was on the other end of the transfers.\""), .cross("Could someone else have used {D}'s login?", "\"It's possible. The log shows the login, not the face. But the chats came from {D}'s phone.\""), .cross("Did {D} confess?", "\"No. {D} did not confess. When we asked, {D} said the exports were for a mailing and that {D.he} had not known what the recipient would do.\"")],
        defenseRole: "Agency manager",
        defenseExam: [.direct("What is your role at the agency?", "\"I'm the agency manager. I assign work to the clerks, oversee client mailings, and I sign off on anything that leaves the office in bulk.\""), .direct("Did you assign {D} a mailing?", "\"I mentioned a mailing in a meeting, but never assigned it to {D} in writing.\""), .direct("How do mailings work?", "\"We use a vendor. A clerk exports a limited list of names and addresses. We never send full files.\""), .direct("Did {D} have a reason to export seventy files?", "\"Not that I know of. A normal mailing only needs names and addresses, so exporting full policy files for seventy people makes no sense to me.\""), .direct("How did {D} behave at work?", "\"Quietly and reliably. {D} never complained about pay, came in on time, and had no discipline problems before this audit.\""), .direct("What did you do when the audit began?", "\"I suspended {D} on the spot, locked the account, and cooperated with the security officer and the outside investigators from then on.\""), .cross("Did you tell {D} to export files?", "\"I did not. I mentioned a possible mailing in general terms in a staff meeting, but I never told {D} to export any particular files.\""), .cross("Did you check {D}'s work?", "\"Not on a daily basis. I trusted my clerks, and I did not review each export before it went out, which I regret.\""), .cross("Is it normal for clerks to use chat?", "\"Not for sending files. We use secure email for anything with policyholder data, and chat is only for quick questions between staff.\""), .cross("Did {D} ask you about the mailing?", "\"Once, in passing, at the coffee station. {D} asked about the mailing and I told {D.him} I would get back to {D.him}.\""), .cross("Did you ever follow up?", "\"No. I forgot, which I should not have, because if I had followed up the exports might have been caught weeks earlier.\"")],
        theory: ("{D} sold policyholder data.", "A mailing."),
        allocution: "\"I made a terrible mistake.\"",
        truths: ("{DL} had no assignment.", "The chat uses an alias."),
        defendant: [.direct("What was your job?", "\"I was a clerk at the insurance agency. I handled policy changes, renewals, and sometimes mailing lists.\""), .direct("Why did you export seventy files?", "\"For a mailing the manager mentioned. I thought it was a renewal reminder and I wanted to get ahead.\""), .direct("Did you send files to someone?", "\"I sent files to a contact who said they'd help with the mailing. I thought it was a mailing house.\""), .direct("Why did you get paid?", "\"The contact said it was a referral fee. I did not ask more. I took it.\""), .direct("Did you know the files would be used to scam people?", "\"No, I did not know the files would be used to scam anyone. I only found that out when the audit started and the security officer called me in.\""), .direct("What are you sorry for?", "\"For trusting someone I did not know, and for not asking any questions when a stranger offered money for what I thought was a routine task.\""), .cross("You sent seventy policyholder files to an alias, didn't you?", "\"Yes, I did, and I should not have. I sent them in several batches over about a month, and I never stopped to ask who was behind the alias.\""), .cross("You were paid in cryptocurrency, weren't you?", "\"I was. It was a small amount compared with what I'd have been paid for a real job.\""), .cross("You had no written assignment for a mailing, did you?", "\"No. It was a verbal mention from the manager in a meeting, and I did not ask for anything written down before I started.\""), .cross("The policyholders were scammed, weren't they?", "\"I understand they were. I am very sorry for what they went through, especially the ones who lost savings, and I wish I could undo it.\""), .cross("You never checked who the alias was, did you?", "\"No, I did not. I never checked who the alias was or whether the mailing house was real, and I should have done both.\"")],
        openings: ("An insurance agency clerk, {D}, exported seventy policyholder files over a month and sent them to an alias in chat, and cryptocurrency payments arrived afterward. Policyholders were then phished using details only the agency had. You will hear from the agency's security officer.", "{D} thought the exports were for a mailing the manager had mentioned, and the person who asked for the files said it was a mailing house. {D} was foolish, not a scammer. The State must prove {D} knew the files would be used to defraud."),
        closings: ("Seventy files, an alias in a chat, cryptocurrency payments to {D}, and policyholders phished with details only the agency had. One investor lost savings. The logs and chats are clear.", "A manager mentioned a mailing, {D} had no written assignment, and the alias was never traced. {D} was careless but did not know. The State must prove {D} intended to help scammers."),
        timeline: [(-30, "Exports begin."), (0, "Week 4: phishing."), (0, "Week 5: the audit."), (1, "{DL} is suspended.")],
        identified: "Logs and chats.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "I lost my savings.",
        doctrines: ["burdenOfProof"])

    static let fakeFundraiserOnlineV1 = SmallCases.make(
        key: "story.fakeFundraiserOnline",
        category: .whiteCollar,
        headlines: ["Organizer Ran Fake Hurricane Relief Drive and Collected $95,000", "No Shelter Received Funds"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and other donors, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} ran a hurricane relief drive and collected $95,000 on {DATE}. No shelter received any of it. {DL} says the shelter delays were not {D.his} fault.",
        state: [E(.document, 3, "Platform Records", "$95,000 paid to {D}."), E(.statement, 3, "Shelter", "No funds received."), E(.digital, 2, "Posts", "Photos copied from news.")],
        defense: [E(.statement, 1, "Delay", "{DL} says shelter delays held funds.")],
        role: "Donor",
        exam: [.direct("How did you come to give to {D}'s relief drive?", "\"I saw posts after the hurricane asking for donations for shelters. {D}'s drive looked organized, with photos and updates, so I donated.\""), .direct("How much did you give?", "\"$250 through the platform. It seemed like a good cause, and I shared the link with friends and family.\""), .direct("What did the posts say?", "\"They said every dollar would go to local shelters taking in displaced families. The photos showed flooded streets and volunteers.\""), .direct("What happened after two months?", "\"I asked for an update because I never saw one. {D} replied slowly and vaguely, and then stopped answering.\""), .direct("What did you find out?", "\"I called a shelter named in the posts. They said they received no funds from {D}'s drive.\""), .direct("How much was raised in total?", "\"About $95,000 in total, according to the platform records, all of it paid out to {D}'s account over the two months the drive was running.\""), .cross("Did you see {D} spend any of the money?", "\"No, I did not see {D} spend anything. All I have is the platform records and what the shelter told me when I called.\""), .cross("Did {D} say anything about shelter delays?", "\"Yes, in a message. {D} said the shelters were slow to process paperwork and that funds were being held.\""), .cross("Were the photos in the posts real?", "\"I later learned they were copied from news stories. I don't know if all were.\""), .cross("Did {D} send money to any shelter?", "\"I do not know. I only called one shelter, and they said they received nothing, so I cannot speak to the others {D} named.\""), .cross("Why did you trust {D}?", "\"It looked professional, with photos, updates, and a clear goal, and a friend I trust shared it, so I assumed it was legitimate.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("How do you know {D}?", "\"I have known {D} since high school, and I helped {D} share the relief drive on social media the night the hurricane hit.\""), .direct("What was {D}'s reaction to the hurricane?", "\"Heartbroken. {D} watched the news coverage and wanted to do something right away, and started the page that same night.\""), .direct("Did {D} send money to a shelter?", "\"Yes. {D} told me {D.he} sent $4,000 to one shelter and showed me a receipt on {D.his} phone.\""), .direct("Why were the other transfers delayed?", "\"{D} said shelters wanted paperwork and had not set up accounts. I don't know the details.\""), .direct("How did {D} handle the money?", "\"Messily. {D} put everything in one account and was not careful about tracking where the money went or what was owed.\""), .direct("How did {D} react to donors' questions?", "\"With stress. {D} avoided donors' questions because {D.he} did not have answers, and the more they asked, the more {D} hid.\""), .cross("Did you see where the rest of the money went?", "\"No. I never saw the account and I never saw how the money moved. I only helped share the link with people I know.\""), .cross("Did you know about the boat?", "\"I heard about the boat later and was upset. It did not match the {D} I thought I knew, and I told {D} so.\""), .cross("Did you help {D} make the drive?", "\"I helped with sharing the drive on social media and gave out the link. I did not manage the money or the account.\""), .cross("Did you donate?", "\"Yes, I gave $100. I did not get an update either, so I know exactly how the other donors felt when the silence came.\""), .cross("Do you believe the delays were real?", "\"I believe some of them were real. Shelters do move slowly with paperwork. I cannot tell you how much of the delay was real and how much was an excuse.\"")],
        theory: ("{D} faked a relief drive.", "A delay."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} bought a boat.", "{DL} sent $4,000 to a shelter."),
        defendant: [.direct("Why did you start the relief drive?", "\"The hurricane devastated a nearby county, and I wanted to help. I started a page and shared it widely.\""), .direct("How much did you raise?", "\"About $95,000 from many donors. It was far more than I expected, and I got swept up in how quickly the money was coming in.\""), .direct("Where did the money go?", "\"Some went to a shelter. I sent $4,000 to one, and I planned to send more as paperwork cleared.\""), .direct("Why did the shelters not receive more?", "\"The shelters were slow to set up the transfers. I was told funds needed documentation I had not finished.\""), .direct("What about the photos?", "\"I used photos from news stories to illustrate the posts. I should not have. I did not think about donors.\""), .direct("What did you spend on yourself?", "\"I'm not going to hide that I spent money that was not mine to spend.\""), .cross("You collected $95,000 and sent $4,000 to a shelter, didn't you?", "\"Yes, that is right. $95,000 came in, and only $4,000 went to a shelter. I understand how bad that ratio looks.\""), .cross("You bought a boat, didn't you?", "\"I did buy a boat with some of the money. I am ashamed of it, and I know it was not mine to spend that way.\""), .cross("The photos in your posts were copied, weren't they?", "\"Yes, they were. I took photos from news stories to illustrate the posts, and I should not have used pictures that were not mine.\""), .cross("You stopped answering donors, didn't you?", "\"I did. I stopped answering donors because I was embarrassed and had no good answers, and the silence only made everything worse.\""), .cross("The shelters you named never got your funds, did they?", "\"One shelter got the $4,000 I sent. The others named in the posts did not receive anything from me, and I have no excuse for that.\"")],
        openings: ("{D} ran a hurricane relief drive that collected $95,000 from donors, and a shelter named in the posts says it received nothing from it. The photos were copied from news stories, and {D} bought a boat. You will hear from a donor who gave $250.", "{D} did send $4,000 to a shelter and says shelter paperwork delayed the rest. A friend who helped share the drive will tell you how {D} handled the money. The State must prove {D} never meant to deliver it."),
        closings: ("$95,000 in, $4,000 out, and a boat in between. The photos came from the news, and the donors got silence. That is theft by false pretenses.", "A real hurricane, a real shelter payment, and a documented delay in paperwork. {D} was messy and ashamed. The State must prove {D} planned from the start to keep the money."),
        timeline: [(-60, "The drive begins."), (0, "Month 2: donors ask."), (0, "Month 2: the shelter says no."), (1, "{DL} is charged.")],
        identified: "Platform records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I felt sick.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let churchInvestmentPonziV1 = SmallCases.make(
        key: "story.churchInvestmentPonzi",
        category: .whiteCollar,
        headlines: ["Retired Teacher's Farmland Fund Paid Early Investors With Later Deposits, $520,000 Lost", "Neighbors Learn the 'Land' Doesn't Exist"],
        law: "securitiesFraud",
        threshold: 8,
        spec: "Offered and sold securities by fraud to {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a retired teacher, told neighbors about a farmland fund that would pay 15% returns. Early investors were paid with later deposits. Investors put in $520,000 over three years. Bank records showed no land purchases and large transfers to {D}'s personal accounts. A recorded presentation promised 'no risk'. {DL} says the land deals fell through and the money was spent on legal fees.",
        state: [E(.document, 3, "Bank Records", "No land purchases; transfers to {D}."), E(.document, 3, "Offering Papers", "A promise of 15% and 'no risk'."), E(.statement, 2, "Investor", "Paid at first, then nothing."), E(.digital, 1, "Recorded Presentation", "'No risk' repeated.")],
        defense: [E(.statement, 1, "Deals Fell Through", "{DL} says the land deals failed."), E(.document, 1, "Legal Invoices", "Some legal fees paid.")],
        role: "Securities investigator",
        exam: [.direct("What is your role in this case?", "\"I'm a securities investigator. I reviewed the fund's bank records, the offering papers, and the investor statements after an investor complained.\""), .direct("What was the fund?", "\"{D}, a retired teacher, told neighbors about a farmland fund that would pay 15 percent annual returns. Over three years, investors put in $520,000.\""), .direct("What did the bank records show?", "\"There were no land purchases. The money came in from investors, and large transfers went out to {D}'s personal accounts.\""), .direct("How were early investors paid?", "\"With deposits from later investors. The first payouts came about a year after the fund began, funded by new money.\""), .direct("What did the offering papers promise?", "\"15 percent returns and, in the recorded presentation, no risk, repeated several times. Real farmland funds do not promise no risk.\""), .direct("What happened to payouts?", "\"They stopped about ninety days before an investor complained. Regulators subpoenaed the records two weeks after that.\""), .cross("Did {D} spend all of the money on personal items?", "\"Some of it went to legal fees, which the invoices support. I can't say every transfer was personal.\""), .cross("Were any land deals pursued?", "\"The records do not show any closings. There may have been attempts that failed.\""), .cross("Did {D} make the presentation in good faith?", "\"I cannot read {D}'s mind, so I cannot say what {D} believed. I can say that the claims in the presentation were false.\""), .cross("Was {D} an experienced investor?", "\"No. {D} is a retired teacher with no securities background that I know of.\""), .cross("Did investors get anything back?", "\"A few early investors received payouts, but most lost their principal. The early payouts were funded by deposits from later investors.\"")],
        theory: ("{D} ran a scheme paying old investors with new money.", "A retired teacher whose land deals failed."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} bought a vacation home with investor money.", "{DL} told one investor to 'keep this between us'."),
        defendant: [.direct("Why did you start the fund?", "\"I wanted to help neighbors earn more than the bank paid. I believed farmland was a safe investment.\""), .direct("What did you do with the money?", "\"I tried to buy land. The deals fell through, and I spent some on legal fees to try to save them.\""), .direct("Why did you pay early investors?", "\"I wanted to keep my promise. I used new deposits because the land money was tied up.\""), .direct("Did you intend to cheat anyone?", "\"No. I thought the deals would work out, and I never meant to cheat a neighbor. I was in over my head and too proud to say so.\""), .direct("Why did you say no risk?", "\"I believed that. I was a teacher, not a financial professional, and I was wrong.\""), .direct("What would you tell investors?", "\"That I am sorry, that I wanted to make it right, and that I still do. I did not plan for any of them to lose their savings.\""), .cross("You paid early investors with later deposits, didn't you?", "\"Yes, I did, and I see now exactly how that works. It was wrong, and I should have stopped when the land money was tied up.\""), .cross("You never bought any land, did you?", "\"No, not a single acre. The deals fell through before anything closed, and I did not tell the investors that at the time.\""), .cross("You transferred money to your personal accounts, didn't you?", "\"Yes, some of it went to my personal accounts, and I used that money for my own expenses. I am not going to deny that.\""), .cross("You told one investor to keep this between us, didn't you?", "\"I said something like that to one investor. I was embarrassed that the payouts had stopped and I did not want it spreading around town.\""), .cross("You bought a vacation home during this time, didn't you?", "\"Yes, I used some of the money toward a vacation home during that time. It was wrong, and I knew it was not mine to spend.\"")],
        openings: ("{D}, a retired teacher, told neighbors about a farmland fund paying 15 percent. Investors put in $520,000 over three years, the bank records show no land purchases, and early investors were paid with later deposits. A recorded presentation promised no risk.", "{D} is a retired teacher who believed in farmland deals that fell through, and who spent part of the money on legal fees trying to save them. {D} was in over {D.his} head. The State must prove {D} meant to cheat."),
        closings: ("$520,000, no land, early payouts from later investors, and transfers to {D}'s personal accounts. A recorded presentation promised no risk. This is a classic Ponzi scheme.", "A retired teacher with no securities training, real legal invoices, and land deals that failed. {D} was reckless but did not plan to defraud. The State must prove intent."),
        timeline: [(-1095, "The fund begins."), (-730, "The first early payouts."), (-90, "Payouts stop."), (0, "An investor complains."), (14, "Regulators subpoena the records.")],
        identified: "Bank records.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let homeBuilderDepositsV1 = SmallCases.make(
        key: "story.homeBuilderDeposits",
        category: .whiteCollar,
        headlines: ["Pool Builder Took Deposits for Eleven Backyards and Dug None", "Holes Never Started"],
        law: "falsePretenses100k",
        threshold: 8,
        spec: "Obtained over $100,000 by false pretenses from {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a pool builder, took $142,000 in deposits from eleven families on {DATE} and dug no pool. {DL} says permits stalled.",
        state: [E(.document, 3, "Deposit Records", "$142,000 from eleven families."), E(.statement, 3, "Family", "'He promised a spring start.'"), E(.document, 2, "Permit Office", "No permits pulled.")],
        defense: [E(.statement, 1, "Permits", "{DL} says permits stalled.")],
        role: "Homeowner",
        exam: [.direct("How did you come to hire {D}?", "\"We wanted a backyard pool, and {D}, a local pool builder, gave us a quote. {D} promised a spring start and asked for a deposit.\""), .direct("How much did you pay?", "\"A deposit of $14,000, which was a big part of our savings. I paid by check and got a signed contract.\""), .direct("What happened after you paid?", "\"Nothing. No crew showed up, no permit sign went up, and every time I called I got a new reason for the delay.\""), .direct("What did the county permit office tell you?", "\"No permits had been pulled for our address. I called the office after six months and they had nothing on file.\""), .direct("Were you the only family affected?", "\"No. Eleven families gave deposits, totaling $142,000. We found each other after a post in a neighborhood group.\""), .direct("What did that do to your family?", "\"We lost our down payment on the pool and had to cancel other plans. It put a strain on us.\""), .cross("Did {D} say permits were the problem?", "\"Yes. {D} said the county was slow. I called and learned no applications had been submitted, so I do not know.\""), .cross("Did {D} return any money?", "\"No. {D} did not return a dollar to my family or, as far as I know, to any of the other families who put down deposits.\""), .cross("Did you read the contract?", "\"Yes, I read it. It said work would begin in the spring, depending on permits, which is why {D} could say the permit office was to blame.\""), .cross("Did the contract say when permits were to be applied for?", "\"It did not give a date. The contract said permits would be applied for but never said when, so there was nothing to hold {D} to.\""), .cross("Did you visit {D}'s shop?", "\"Once, early on. It looked busy, with trucks parked outside and equipment in the lot, so I had no reason to worry at that point.\"")],
        defenseRole: "Permit clerk",
        defenseExam: [.direct("What is your job at the county?", "\"I am a permit clerk at the county office. I process applications for building and pool permits and talk to builders about what is missing.\""), .direct("Was there a backlog that year?", "\"Yes. We were short on staff, and wait times ran several months that year. The delays are documented in our logs and in complaints we received.\""), .direct("Did {D} submit permits?", "\"I recall one application from {D}. It was incomplete, and we sent it back.\""), .direct("Did {D} follow up?", "\"Not much. {D} called once and asked about timing, but did not ask what the application needed or whether anything was missing.\""), .direct("How long do permits take?", "\"Usually six to eight weeks, but that year it stretched well beyond that. Even so, nothing can be approved until an application is filed.\""), .direct("Did you see a pattern?", "\"Many builders complained about the delay. It was a real problem that year, and I do not want to understate what contractors went through.\""), .cross("Did {D} submit eleven applications?", "\"No. Only one that I recall. It was incomplete, so we sent it back with a notice, and I do not remember seeing it again.\""), .cross("Were the others ever filed?", "\"Not that I saw. I do not recall a second application from {D}, and I never saw ten others come through the counter.\""), .cross("Did you tell {D} what was missing?", "\"Yes. We sent a written notice on the application that came in, listing what was missing, and the file shows it went out.\""), .cross("Would a delay explain no applications?", "\"It would not. A delay in processing is different from no application at all. An application must be filed before the clock even starts.\""), .cross("Did {D} ever ask for help?", "\"Not that I remember. {D} never asked me for help finishing the paperwork, and I would have been glad to walk through it.\"")],
        theory: ("{D} took deposits.", "Stalled permits."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} spent deposits on trucks.", "A county delay is documented."),
        defendant: [.direct("What is your business?", "\"I build residential pools. I've done it for about ten years, mostly in this county.\""), .direct("Why did you take deposits from eleven families?", "\"I wanted to lock in work for the spring. Deposits are how pool builders schedule.\""), .direct("Why did you not start the pools?", "\"Permits stalled at the county. There was a backlog that year, and I kept waiting for approval before moving a crew onto any of these jobs.\""), .direct("Did you submit applications?", "\"I filed some paperwork, but not all of it. I was disorganized, I fell behind on the applications, and I did not tell the families that.\""), .direct("Where did the deposits go?", "\"Some went to supplies I had already ordered. Some went to trucks and equipment I needed to run the business, instead of staying set aside.\""), .direct("Do you plan to return the money?", "\"I want to, but I do not have the money right now. I am ashamed, and I would like to work out a repayment plan.\""), .cross("You took $142,000, didn't you?", "\"Yes, that is the total. Eleven families gave me deposits that added up to $142,000, and I have not returned any of it yet.\""), .cross("No permits were pulled, were they?", "\"Not that I can show. I am not hiding that. I cannot produce a permit for any of those eleven addresses.\""), .cross("You spent deposits on trucks, didn't you?", "\"Yes, some of it. A few thousand went toward trucks, and I know that was not what the deposits were meant for.\""), .cross("You told families the county was slow, didn't you?", "\"I did, and it was partly true, because the county really was slow. But I also knew I had not filed most of the applications.\""), .cross("You did not return calls from some families, did you?", "\"No, I avoided some of them. I was embarrassed and did not know what to say, and that was cowardly of me.\"")],
        openings: ("{D}, a pool builder, took $142,000 in deposits from eleven families, promised a spring start, and dug no pool. The county permit office has no permits for any of those addresses. You will hear from a homeowner who paid.", "The county's permit office had a documented backlog that year, and {D} was a small builder waiting in the queue. A permit clerk will tell you the delay was real. The State must prove {D} never intended to build."),
        closings: ("Eleven families, $142,000, a promise of spring, and not one permit pulled. {D} bought trucks with their savings. {V} lost a down payment.", "A real backlog at the county, a small builder in a long queue, and deposits that went to supplies and equipment. The State must prove {D} took the deposits with no intention of building."),
        timeline: [(-240, "The first deposit."), (0, "Month 6: no permits."), (0, "Month 8: families complain."), (1, "{DL} is charged.")],
        identified: "Deposit records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "We lost our down payment.",
        doctrines: ["burdenOfProof"])

}
